properties.query:
let window = 60m;
let business_start_hour = 8;
let business_end_hour = 18;
let hour_now = datetime_part("hour", now());
OberKeySummary_CL
| where TimeGenerated > ago(window) and access_key == "(heartbeat)"
| summarize rows = count(), total_requests = sum(requests), first_row = min(TimeGenerated)
| where rows > 0 and total_requests == 0 and first_row <= ago(window - 10m)
| where hour_now >= business_start_hour and hour_now < business_end_hour
| where dayofweek(now()) between (1d .. 5d)
| extend TimeGenerated = now(), rule = "no_traffic"
